import { DialogueAudio } from './dialogue-audio.js';
import { SimpleAttack, evasionAction, comboHint, attackLabel } from './simple-controls.js';
import { StoryDirector, IDENTITIES, identityFor, voiced, VOICE_ON } from './story3d.js';
import { StoryView, journalHTML } from './story-view.js';
import { GameAudio } from './audio3d.js';
import { CombatLabels } from './combat-labels.js';
import { CampaignCombat } from './campaign3d.js';
import { drawBattleMap } from './battle-map.js';
import { ArenaCombat, ENEMIES } from './combat3d.js';
import { InkWorld } from './world3d.js';
const $=id=>document.getElementById(id),canvas=$('scene');
const world=new InkWorld(canvas),labels=new CombatLabels($('combat-labels')),audio=new GameAudio();
const dialogue=new DialogueAudio(audio);
let game=new ArenaCombat(2),mode='title',chosen=2,campaign=false,paused=false,locked=true,last=0,accumulator=0,resultTimer=0,messageTimer=0,messageCooldown=0,drag=null,touchMove={x:0,z:0},touchSprint=false;
let activeStick=null,keys=new Set(),heldTouches=new Map(),elapsed=0,frames=0,fps=0;
const attackInput=new SimpleAttack(name=>action(name));
const playable=()=>mode==='playing'&&!paused&&game.status==='playing';
const guarding=()=>keys.has('k')||keys.has('e')||[...heldTouches.values()].includes('guard');
let storyStorage=null;try{storyStorage=localStorage;}catch{}
const story=new StoryDirector(storyStorage),storyUI=new StoryView({next:()=>stepStory(false),skip:()=>stepStory(true)});
let afterStory=null,heldScene=null,cameraHeld=0;
function enterStory(view,done=null){if(!view)return false;afterStory=done;paused=true;accumulator=0;clearInput();$('message').style.opacity='0';storyUI.show(view);speakStory(view);return true;}
function stepStory(skip){const view=skip?story.skip():story.advance();storyUI.show(view);if(view){speakStory(view);return;}dialogue.stop();clearInput();accumulator=0;paused=false;const done=afterStory;afterStory=null;if(done)done();else{canvas.focus({preventScroll:true});if(campaign)announce(game.objective().goal,2.2);}}
function speakStory(view){$('story-voice').hidden=!view.voiced;if(view.voiced)dialogue.play(`${view.id}-${view.index}`);else dialogue.stop();}
function resetStoryView(){dialogue.stop();story.cancel();storyUI.hide();storyUI.clearBark();afterStory=null;heldScene=null;}
// A fight is on while roused foes are close; between fights the road is walked with a free camera that looks where it leads.
const engaged=()=>!campaign||game.engaged();
// The page that follows a cleared chapter waits until the last foe has fallen and the hero's own move is done.
function releaseScene(){const held=heldScene;heldScene=null;if(!held)return;const scene=story.event(held.event,game);if(scene)enterStory(scene);}
function showJournal(){showModal('志怪錄 · 借名山','TALES OF BORROWED NAMES',journalHTML(story),[{text:'合卷',primary:true,action:closeModal}]);}
const small=()=>matchMedia('(pointer:coarse)').matches||innerWidth<700;
const names={w:'w',a:'a',s:'s',d:'d',ArrowUp:'w',ArrowDown:'s',ArrowLeft:'a',ArrowRight:'d',Shift:'shift',' ':'roll'};
const normalize=k=>names[k]||k.toLowerCase();
new ResizeObserver(()=>{world.resize();$('touch').hidden=mode!=='playing'||!small();}).observe(canvas);
function announce(text,duration=1.3){$('message').textContent=text;$('message').style.opacity='1';messageTimer=duration;}
function direction(){const x=(keys.has('d')?1:0)-(keys.has('a')?1:0)+touchMove.x,z=(keys.has('w')?1:0)-(keys.has('s')?1:0)+touchMove.z;return world.movement(x,z,locked&&game.enemy.hp>0&&engaged(),game.player,game.enemy);}
function clearInput(){attackInput.clear();keys.clear();heldTouches.clear();touchMove={x:0,z:0};touchSprint=false;activeStick=null;$('joystick').classList.remove('sprinting');$('joystick').querySelector('i').style.transform='';drag=null;}
function action(name){if(mode!=='playing'||paused||game.status!=='playing')return;
 if(name==='lock'){locked=!locked;announce(locked?'鎖 定':'自由鏡頭 · 拖曳旋轉',.85);return;}
 if(name==='light'||name==='heavy')locked=true;
 const d=direction();if(name==='evade')name=evasionAction(d,game.player.yaw,game.player.dashCooldown);if(name==='special'&&game.player.qi<100){announce('墨氣未滿',.7);return;}
 if(name==='heal'&&game.player.flasks===0){announce('回元飲已盡',.7);return;}
 return game.action(name,d.x,d.z);
}
// The title screen keeps an idle fight behind the cover art.
function rest(){chosen=2;campaign=false;game=new ArenaCombat(chosen);world.setEnemy(ENEMIES[chosen].id);}
function begin(index=chosen,trial=false,retry=false){if(!world.assetsLoaded)return;resetStoryView();chosen=index;game=trial?(retry&&game.campaign?game.retryCheckpoint():new CampaignCombat()):new ArenaCombat(index);labels.clear();campaign=trial;audio.reset();audio.unlock().then(refreshAudioStatus);world.setEnemy(game.spec.id);world.resetCamera();mode='playing';paused=false;locked=true;resultTimer=0;accumulator=0;clearInput();$('app').classList.add('playing');for(const id of['title-screen','scene-note','footer','overlay'])$(id).hidden=true;$('hud').hidden=false;$('touch').hidden=!small();$('boss-name').textContent=identityFor(game).name;$('boss-subtitle').textContent=identityFor(game).title;updateHUD();announce(trial?game.objective().goal:game.spec.id==='wolf'?'留意撲咬 · 側閃後反擊':'觀察起手 · 留意遠招',1.2);canvas.focus({preventScroll:true});enterStory(story.start({campaign:trial,opponent:index,retry,stage:game.stage||0}));}
function home(){$('top-chapter').textContent='鎮 祟 寺 · 雨 夜';resetStoryView();audio.reset();labels.clear();messageTimer=0;messageCooldown=0;$('message').textContent='';mode='title';paused=false;clearInput();$('app').classList.remove('playing');for(const id of['title-screen','scene-note','footer'])$(id).hidden=false;for(const id of['hud','touch','overlay'])$(id).hidden=true;$('message').style.opacity='0';rest();world.resetCamera();$('campaign').focus({preventScroll:true});}
function showModal(title,kicker,body,actions,close=true){dialogue.stop();storyUI.clearBark();paused=mode==='playing';clearInput();$('modal-title').textContent=title;$('modal-kicker').textContent=kicker;$('modal-body').innerHTML=body;$('modal-actions').replaceChildren();for(const a of actions){const b=document.createElement('button');b.textContent=a.text;b.className=a.primary?'primary':'secondary';b.addEventListener('click',a.action);$('modal-actions').append(b);}$('close-modal').hidden=!close;$('overlay').hidden=false;($('modal-actions').querySelector('button')||$('close-modal')).focus({preventScroll:true});}
function closeModal(){if($('close-modal').hidden)return;if(mode==='playing'&&game.status!=='playing'){showResults();return;}$('overlay').hidden=true;paused=false;accumulator=0;if(mode==='playing')canvas.focus({preventScroll:true});else $('campaign').focus({preventScroll:true});}
function pause(){if(story.current)return;if(mode!=='playing'||game.status!=='playing')return;if(!$('overlay').hidden){closeModal();return;}showModal('暫歇筆鋒','A MOMENT OF STILLNESS',campaign?'<p>沿山道向北，清空據點後關口開啟；每過一關暫存進度，重試從本章入口開始。<br>路旁發光的碑陰可拓下名字（共 12 張），土地龕能補滿回元飲。</p>':'<p>看清起手，留一分精力，等一個破綻。</p>',[{text:'繼續對戰',primary:true,action:closeModal},{text:'志怪錄',action:showJournal},{text:campaign?'重試此區':'重試此戰',action:()=>begin(chosen,campaign,true)},{text:'回到卷首',action:home}]);}
function showHelp(){showModal('三鍵入畫','SIMPLE CONTROLS',`<p class="simple-intro">先記住攻、閃、擋。招式都在，同一顆按鈕依按法與時機變招。</p><div class="simple-guide"><div><kbd>J ／ 左鍵</kbd><strong>攻擊</strong><span>短按連斬 · 長按重擊<br>破勢或反擊時機出現，直接按攻擊。</span></div><div><kbd>空白鍵</kbd><strong>閃身</strong><span>向前＋閃：疾衝 · 左右＋閃：側閃<br>無方向：後撤 · 疾衝後按攻擊：拔斬</span></div><div><kbd>K ／ 右鍵</kbd><strong>防禦</strong><span>按住格擋 · 快命中時按下：彈反<br>震地與裂地波仍須閃避。</span></div></div><p>WASD / 方向鍵移動；手機用左側搖桿。<br>自動鎖敵，擊倒後自動換敵；不必反覆按鎖定。</p><div class="simple-utilities"><span><kbd>R</kbd> 回元飲</span><span><kbd>F</kbd> 墨氣絕技</span><span><kbd>Esc</kbd> 暫停</span></div><details class="advanced-controls"><summary>想多變招？展開招式與鏡頭操作</summary><p>連按五下：五段連斬，第四刀雙燕迴翔（兩斬），第五刀崩山斷（震開身周）。<br>第一刀出刀途中長按攻擊：挑月斬。<br>第二刀起出刀途中長按攻擊：迴風掃蕩。<br>奔跑中（Shift＋方向；手機把搖桿推出圈外）按攻擊：躍淵斬，躍前落地橫掃一圈。<br>按住防禦＋短按攻擊：飛墨斬，擲出墨刃貫穿三敵（墨氣 20）。<br>按住防禦＋長按攻擊：敕令 · 鎮，插劍震破周圍架勢（墨氣 40）。<br>站定長按攻擊：蓄勢破甲；每次長按只出一招。<br>精準閃避或彈反後，按攻擊接乘隙反斬。<br>敵人破勢時靠近，按攻擊施放鎮魂處決。</p><p>拖曳場景可轉動鏡頭，攻擊時會重新鎖敵。<br>保留選用操作：Q 切換鎖定、T 換敵、Shift 奔跑、C 直接疾衝、E 也可防禦。</p></details>`,[{text:'開始揮刀',primary:true,action:closeModal}]);}
function showAudio(){
 audio.unlock().then(refreshAudioStatus);
 showModal('聲音設定','SOUND & MUSIC',`<p class="audio-caption">配樂留在遠處，刀鋒落在眼前。<br>音量設為 0 即靜音，設定會保留。</p><div class="audio-setting"><label for="music-volume">音樂</label><output id="music-value">${Math.round(audio.settings.music*100)}%</output><input id="music-volume" type="range" min="0" max="100" step="1" value="${Math.round(audio.settings.music*100)}"></div><div class="audio-setting"><label for="effects-volume">音效</label><output id="effects-value">${Math.round(audio.settings.effects*100)}%</output><input id="effects-volume" type="range" min="0" max="100" step="1" value="${Math.round(audio.settings.effects*100)}"></div>${VOICE_ON?`<div class="audio-setting"><label for="voice-volume">對白</label><output id="voice-value">${Math.round(audio.settings.voice*100)}%</output><input id="voice-volume" type="range" min="0" max="100" step="1" value="${Math.round(audio.settings.voice*100)}"></div>`:''}<p id="audio-status" class="audio-status" role="status"></p><p class="audio-caption">進入交戰時淡入戰鬥配樂；暫停時降低音量，切換到其他視窗時靜音。</p><p class="audio-credits">素材與授權：<a href="assets/audio/CREDITS.html" target="_blank" rel="noopener">${VOICE_ON?'Higgsfield／ElevenLabs 配音 · ':''}音樂與音效來源</a></p>`,[{text:'完成',primary:true,action:closeModal}]);
 for(const channel of VOICE_ON?['music','effects','voice']:['music','effects'])$(channel+'-volume').addEventListener('input',event=>{const value=Number(event.target.value);audio.setVolume(channel,value/100);$(channel+'-value').textContent=value+'%';});refreshAudioStatus();
}
function refreshAudioStatus(){const s=audio.snapshot();$('sound').querySelector('span').textContent=s.state==='unavailable'?'未啟用':s.failed.length?'部分缺失':'設定';const node=$('audio-status');if(!node)return;node.textContent=s.state==='unavailable'?'目前無法啟用音訊；遊戲可繼續，請重新整理後再試。':s.failed.length?'部分素材載入失敗；可正常遊玩，重新整理可重試。':s.state==='ready'?'音訊已就緒 · 走位、劍擊與配樂分開混音':'正在載入音訊素材…';}
function showResults(){const won=game.status==='won',final=campaign&&won,actions=[];actions.push({text:won?'再戰一回':campaign?'從此區再起':'重新挑戰',primary:true,action:()=>begin(chosen,campaign,!won)});actions.push({text:'回到卷首',action:home});showModal(won?(final?'名字還給人間':'此戰，已定'):'墨盡 · 再起',won?'VICTORY':'FALLEN, NOT FORGOTTEN',`<p>${won?(final?'借名契已毀。受拘的魂魄各得歸處，無名狀上重新浮出字跡。':`已擊敗${IDENTITIES[game.spec.id].name}。`):game.spec.hint}</p><div class="result-stats"><div><b>${Math.ceil(game.time)}s</b><small>交鋒時間</small></div><div><b>${game.stats.hits}</b><small>有效命中</small></div><div><b>${game.stats.parries}</b><small>成功彈反</small></div><div><b>${game.stats.heals}</b><small>使用回元飲</small></div></div>${campaign?`<p>擊破 ${game.kills} · 最高連擊 ${game.bestCombo} · 名拓 ${game.rubbings()} / 12</p>`:''}<p>精準閃避 ${game.stats.perfectDodges} 次 · 反擊命中 ${game.stats.counters} 次 · 鎮魂處決 ${game.stats.executions} 次</p>`,actions,false);}
function updateHUD(){const p=game.player,e=game.enemy;const hint=comboHint(game,small());$('combo-hint').hidden=!hint;$('combo-hint').textContent=hint;$('boss-status').hidden=campaign&&!game.engaged()&&game.status==='playing';$('battle-map').hidden=!campaign;$('objective').hidden=!campaign;$('boss-name').textContent=identityFor(game).name;$('boss-subtitle').textContent=identityFor(game).title;if(campaign){const o=game.objective();$('objective-title').textContent=`${o.stage+1} / ${o.stages} · ${o.name}`;$('map-zone').textContent=o.zone;$('top-chapter').textContent=[...o.zone].join(' ')+' · 雨 夜';$('objective-goal').textContent=o.goal;$('battle-count').textContent=`擊破 ${o.kills} · 剩餘 ${o.remaining} · 名拓 ${o.rubbings}/12`;$('combo-count').textContent=o.combo>1?`${o.combo} 連擊`:'';drawBattleMap($('minimap'),game);}$('dash-hint').textContent=p.state==='dash'?'按攻擊 · 疾風拔斬':'向前＋閃身：疾衝';const input=attackInput.snapshot();$('attack-button').style.setProperty('--charge',`${input.charge*100}%`);$('attack-button').classList.toggle('charging',input.charge>0);$('attack-button').setAttribute('aria-pressed',String(input.held));$('attack-button').querySelector('b').textContent=attackLabel(game);$('attack-button').querySelector('small').textContent=game.guardArt?.('light')?(game.guardArt('heavy')?'短按飛墨 · 長按鎮':'短按飛墨斬'):game.canLeap?.()?'躍淵斬':'短按斬 · 長按重';$('special-button').classList.toggle('ready',p.qi>=100);$('special-button').setAttribute('aria-disabled',String(p.qi<100));$('special-button').querySelector('small').textContent=p.qi>=100?'已就緒':`${p.qi}%`;$('heal-button').querySelector('small').textContent=`${p.flasks} 次`;$('heal-button').setAttribute('aria-disabled',String(p.flasks===0||p.hp>=p.maxHp));$('hp-number').textContent=`${p.hp} / ${p.maxHp}`;$('hp-fill').style.width=`${p.hp/p.maxHp*100}%`;$('stamina-fill').style.width=`${p.stamina}%`;$('stamina-number').textContent=Math.floor(p.stamina);$('qi-fill').style.width=`${p.qi}%`;$('qi-label').textContent=p.qi>=100?'墨氣已滿 · F':`墨氣 ${p.qi} / 100`;$('flasks').textContent=p.flasks;$('boss-number').textContent=`${e.hp} / ${e.maxHp}`;$('boss-fill').style.width=`${e.hp/e.maxHp*100}%`;$('posture-fill').style.width=`${(e.exposed?1:e.posture/e.maxPosture)*100}%`;$('lock-label').textContent=!engaged()?'山道 · 探索':locked?'自動鎖敵':'自由鏡頭';$('boss-hint').textContent=game.status==='won'?'山門已破':e.exposed?(game.canExecute()?'按攻擊 · 鎮魂處決':'架勢已破 · 靠近後按攻擊'):p.counterWindow>0?'按攻擊 · 乘隙反擊':game.projectiles.length>0?(game.projectiles.some(s=>s.unblockable)?'裂地波接近 · 側閃避開':'遠程招式接近 · 側閃或彈反'):e.state==='recover'?'連招已盡 · 反擊空檔':e.comboLeft>0?'尚有連招 · 勿急反擊':e.enraged?'殺意轉盛 · 留意變招':'看準出手閃避 → 按攻擊反斬';$('boss-hint').style.color=e.exposed||p.counterWindow>0?'#f0ca82':'';
 $('enemy-warning').textContent=e.state==='windup'?(e.moveData?.projectile?(e.moveData.unblockable?'危 · ':'')+e.moveData.name+' · '+(e.moveData.unblockable?'側閃':(e.sequenceIndex+1)+' / '+e.sequence.length):e.kind==='slam'?'危 · '+(e.moveData?.name||'震地')+' · 閃避':e.moveData?e.moveData.name+' · '+(e.sequenceIndex+1)+' / '+e.sequence.length:e.kind==='thrust'?'直刺將至':e.kind==='pounce'?'撲擊將至':'刀勢已起'):e.exposed?'破 · 按攻擊處決':p.counterWindow>0?'隙 · 按攻擊反斬':'';
 $('enemy-warning').style.color=e.exposed||p.counterWindow>0?'#f0ca82':e.kind==='slam'||e.moveData?.unblockable?'#ffa889':'#edd6a2';
 const point=world.enemyScreen(e);$('reticle').hidden=e.hp<=0||!locked||!engaged()||!point.visible||game.status!=='playing';$('reticle').style.left=`${point.x*100}%`;$('reticle').style.top=`${point.y*100}%`;}
function events(){for(const e of game.drainEvents()){world.effect(e,game);labels.emit(e,game);audio.onEvent(e,game);if(e.type==='gate-open'){heldScene={event:e,delay:2.1};}else{if(e.type==='chapter'&&heldScene)releaseScene();const scene=story.event(e,game);if(scene)enterStory(scene);else{const bark=story.bark(e,game);if(bark){storyUI.bark(bark);if(voiced(bark.id))dialogue.play(bark.id);}}}if(e.type==='rubbing'){const note=story.rubbing(e.id,e.count);if(note)storyUI.bark(note);announce('拓 得 一 名',1.1);}if(e.type==='shrine')announce('土地龕 · 回元飲已滿',1.4);if(e.type==='ambush'){announce('伏 兵',.9);for(const foe of game.enemies)if(foe.arrived===game.time)world.combatVFX.dust?.(foe.x,foe.z,18,2.2);}if(e.type==='phase-break'){announce('借 名 契 · 裂',2.2);world.shake=Math.max(world.shake,.22);}if(e.type==='chapter'){world.setEnemy(game.spec.id);announce(e.name,1.2);}if(e.type==='gate-open'){if(locked){world.orbitYaw=0;world.lockYaw=null;}announce('關口已開 · 向前推進',1.7);}if(e.type==='perfect-dodge'){announce('擦身 · 按攻擊反斬',.85);}if(e.type==='counter')announce('乘 隙 反 斬',.6);if(e.type==='execution')announce('鎮 魂',.9);if(e.type==='parry'){announce('彈 反',.7);}if(e.type==='stagger'){announce('架 勢 崩 解',1);}if(e.type==='guard-break')announce('防 禦 崩 解',.8);if(e.type==='exhausted'&&messageCooldown<=0){announce('精力不足',.6);messageCooldown=1.2;}if(e.type==='healed'){announce('回 元',.6);}if(e.type==='enrage')announce('殺 意 漸 起',1);if(e.type==='victory'||e.type==='defeat'){resultTimer=e.type==='victory'?2.8:1.5;dialogue.stop();storyUI.clearBark();clearInput();announce(e.type==='victory'?'勝 負 已 分':'墨 盡 · 再 起',1.5);}}}
$('story-voice').addEventListener('click',()=>{const view=story.view();if(view){if(dialogue.paused)dialogue.resume();else speakStory(view);}});
$('campaign').addEventListener('click',()=>begin(0,true));$('home').addEventListener('click',()=>mode==='playing'?pause():home());$('help').addEventListener('click',showHelp);$('pause').addEventListener('click',pause);$('close-modal').addEventListener('click',closeModal);$('sound').addEventListener('click',showAudio);$('journal').addEventListener('click',showJournal);$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('app').requestFullscreen();}catch{announce('目前瀏覽器無法切換全螢幕',1.5);}});
window.addEventListener('keydown',e=>{
 if(e.metaKey||e.ctrlKey||e.altKey)return;
 if(story.current){if(e.key==='Escape'){e.preventDefault();if(!e.repeat)stepStory(true);}else if((e.key==='Enter'||e.key===' ')&&![$('story-skip'),$('story-voice')].includes(document.activeElement)){e.preventDefault();if(!e.repeat)stepStory(false);}else if(e.key==='Tab'){e.preventDefault();const buttons=[$('story-next'),$('story-voice'),$('story-skip')],index=buttons.indexOf(document.activeElement);buttons[(index+(e.shiftKey?2:1))%3].focus();}return;}
 if(e.key==='Tab'&&!$('overlay').hidden){const all=[...$('overlay').querySelectorAll('button:not([hidden]),input,a[href],summary')];if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0].focus();}return;}
 if(e.key==='Escape'){if(!$('overlay').hidden&&!$('close-modal').hidden)closeModal();else pause();return;}
 if(mode!=='playing')return;const key=normalize(e.key);if(['w','a','s','d','j','k','q','e','r','f','c','t','roll','shift'].includes(key)){e.preventDefault();if(paused){if(key==='r'&&game.status!=='playing')begin(chosen,campaign,game.status==='lost');return;}keys.add(key);if(!e.repeat){if(key==='c')action('dash');if(key==='t')action('target');if(key==='roll')action('evade');if(key==='j')attackInput.press('keyboard',game);if(key==='q')action('lock');if(key==='r')action('heal');if(key==='f')action('special');}}
});window.addEventListener('keyup',e=>{const key=normalize(e.key);keys.delete(key);if(key==='j')attackInput.release('keyboard',game,{cancel:!playable()});});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(!playable())return;e.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);if(e.button===2){heldTouches.set(`mouse:${e.pointerId}`,'guard');return;}if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,total:0,button:e.button};if(e.pointerType!=='touch')attackInput.press(`mouse:${e.pointerId}`,game);});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||paused)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.total+=Math.abs(dx)+Math.abs(dy);if(drag.total>6){attackInput.release(`mouse:${e.pointerId}`,game,{cancel:true});if(engaged())locked=false;else cameraHeld=4;world.orbit(dx,dy);}drag.x=e.clientX;drag.y=e.clientY;});
// A second mouse button pressed or released while another is held arrives as pointermove, not pointerdown/up: guard held, then attack (or the reverse).
canvas.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||e.button<0)return;const id=`mouse:${e.pointerId}`;if(e.button===2){if(e.buttons&2&&playable())heldTouches.set(id,'guard');else heldTouches.delete(id);}if(e.button===0){if(e.buttons&1){if(playable())attackInput.press(id,game);}else attackInput.release(id,game,{cancel:!playable()||drag?.total>6});}});
canvas.addEventListener('pointerup',e=>{heldTouches.delete(`mouse:${e.pointerId}`);attackInput.release(`mouse:${e.pointerId}`,game,{cancel:!playable()||drag?.total>6});if(drag?.id===e.pointerId)drag=null;});
for(const event of ['pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{heldTouches.delete(`mouse:${e.pointerId}`);attackInput.release(`mouse:${e.pointerId}`,game,{cancel:true});if(drag?.id===e.pointerId)drag=null;});
