const joystick=$('joystick');joystick.addEventListener('pointerdown',e=>{if(!playable())return;e.preventDefault();activeStick=e.pointerId;joystick.setPointerCapture(e.pointerId);stick(e);});function stick(e){if(activeStick!==e.pointerId)return;const r=joystick.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,len=Math.hypot(dx,dy),factor=Math.min(1,38/Math.max(len,1));touchMove={x:dx*factor/38,z:-dy*factor/38};touchSprint=len>r.width/2+8;joystick.classList.toggle('sprinting',touchSprint);joystick.querySelector('i').style.transform=`translate(${dx*factor}px,${dy*factor}px)`;}joystick.addEventListener('pointermove',stick);for(const event of['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(event,()=>{activeStick=null;touchMove={x:0,z:0};touchSprint=false;joystick.classList.remove('sprinting');joystick.querySelector('i').style.transform='';});
for(const b of document.querySelectorAll('[data-action]')){
 b.addEventListener('pointerdown',e=>{if(!playable())return;e.preventDefault();b.setPointerCapture(e.pointerId);heldTouches.set(e.pointerId,b.dataset.action);if(b.dataset.action==='attack')attackInput.press(`touch:${e.pointerId}`,game);else if(b.dataset.action!=='guard')action(b.dataset.action);});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,e=>{heldTouches.delete(e.pointerId);if(b.dataset.action==='attack')attackInput.release(`touch:${e.pointerId}`,game,{cancel:event!=='pointerup'||!playable()});});
 // Keyboard/assistive activation of the on-screen buttons; pointer-generated clicks are already handled above.
 b.addEventListener('click',e=>{if(e.detail!==0||!playable())return;if(b.dataset.action==='attack'){attackInput.press('button',game);attackInput.release('button',game);}else if(b.dataset.action!=='guard')action(b.dataset.action);});
}
function suspend(){dialogue.pause();audio.setHidden(true);clearInput();if(mode==='playing'&&!paused&&game.status==='playing')pause();}window.addEventListener('blur',suspend);window.addEventListener('focus',()=>{audio.setHidden(false);if(story.current)dialogue.resume();});document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();else{audio.setHidden(false);if(story.current)dialogue.resume();}});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();suspend();$('error').hidden=false;$('error-detail').textContent='3D 圖形環境已中斷，請重新載入。';});
function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;elapsed+=dt;frames++;if(elapsed>1){fps=Math.round(frames/elapsed);frames=0;elapsed=0;}
 if(!paused){storyUI.update(dt,dialogue.snapshot());messageCooldown-=dt;if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('message').style.opacity='0';}if(mode==='playing'){
  accumulator+=dt;while(accumulator>=1/60&&!paused){attackInput.update(1/60,game);const d=direction();game.update(1/60,{x:d.x,z:d.z,lock:locked,sprint:keys.has('shift')||touchSprint,guard:guarding()});events();if(heldScene&&!paused&&game.hitStop<=0){heldScene.delay-=1/60;if(heldScene.delay<=0&&!game.ultimate()&&['idle','guard'].includes(game.player.state))releaseScene();}accumulator=Math.max(0,accumulator-1/60);}
  if(resultTimer>0&&!paused){resultTimer-=dt;if(resultTimer<=0){if(!enterStory(story.finish(game.status==='won',game),showResults))showResults();}}
 }}
 if(mode==='playing'&&world.enemyKind!==game.spec.id)world.setEnemy(game.spec.id);$('app').classList.toggle('ultimate',mode==='playing'&&game.status==='playing'&&!!game.ultimate()?.charging);const fighting=engaged();if(mode==='playing'&&campaign&&!paused&&!fighting&&locked){cameraHeld=Math.max(0,cameraHeld-dt);const w=game.waypoint(),p=game.player;if(w&&cameraHeld<=0&&Math.hypot(w.x-p.x,w.z-p.z)>4){const want=Math.atan2(p.x-w.x,p.z-w.z),turn=Math.atan2(Math.sin(want-world.orbitYaw),Math.cos(want-world.orbitYaw));world.orbitYaw+=turn*(1-Math.exp(-dt*1.4));}}world.update(game,{mode,locked:locked&&fighting,dt,paused});audio.update(game,{mode,paused,dt});labels.update(paused?0:dt,game,world,mode==='playing');if(mode==='playing')updateHUD();if(story.current){const state=dialogue.snapshot().state;$('story-voice').textContent=state==='loading'?'配音載入中…':state==='playing'?'重播本句 ↺':state==='failed'?'配音重試 ↻':state==='paused'?'繼續配音 ▷':'重播本句 ▷';}requestAnimationFrame(frame);
}
